import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let T be a right triangle with legs of lengths {triangle_leg_x} (horizontal) and {triangle_leg_y} (vertical), and let R be a rectangle of dimensions {rect_width} by {rect_height}. In T, draw a single segment parallel to the horizontal leg that intersects the other two sides, partitioning T into a smaller right triangle U1 (adjacent to the right-angle vertex) and a trapezoid V1 whose bases are horizontal. In R, draw a single segment from the top-left vertex to a point on the bottom side, partitioning R into a right triangle U2 adjacent to the bottom-left corner and a trapezoid V2 whose bases are the top and bottom sides of the rectangle. Choose the two segments so that U1 is similar to U2 and V1 is similar to V2, and all four pieces are non-degenerate. Among all such choices, the area of U1 attains a minimum. Express this minimum area as m/n in lowest terms and compute m+n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We engineer parameters so that the discriminant in the governing quadratic is a perfect square,
# guaranteeing a rational minimal area.
# Construction:
# Let u = s1^2, h = s2^2 so that t = sqrt(h*u) = s1*s2 is integer.
# Pick v >= 3 and k >= 1, and set w = k*t + v*k^2. This makes the discriminant (t*(t+2vk))^2.
from fractions import Fraction
while True:
    s1 = rng.randint(2, 9)
    s2 = rng.randint(2, 9)
    u = s1 * s1
    h = s2 * s2
    v = rng.randint(3, 12)
    k = rng.randint(1, 6)
    t = s1 * s2
    w = k * t + v * k * k
    # Compute y via the positive root (engineered to be rational): y = t*v*k / (k*t + v*k^2)
    yF = Fraction(t * v * k, k * t + v * k * k)
    if yF <= 0 or yF >= v:
        continue
    # x_cut = u * (1 - y/v)
    x_cutF = Fraction(u) * (Fraction(1) - yF / v)
    if x_cutF <= 0:
        continue
    # Area of U1: A = (1/2) * x_cut * y
    areaF = Fraction(1, 2) * x_cutF * yF
    # Ensure non-trivial sizes and avoid tiny or huge denominators
    if areaF.numerator <= 0 or areaF.denominator <= 0:
        continue
    # Additional mild filters for variety
    if u == v:
        continue
    # All good; return instance
    return {
        'triangle_leg_x': u,
        'triangle_leg_y': v,
        'rect_width': w,
        'rect_height': h
    }

    def verifier(assign):
# Recompute the minimal area from first principles and validate constraints.
# Geometry setup:
# Triangle T with legs u (horizontal), v (vertical). Its hypotenuse is x/u + y/v = 1.
# Cut T by a horizontal line at height y, producing U1 with legs x_cut = u(1 - y/v) and y.
# Rectangle R with width w and height h; cut it by a segment from (0,h) to (X,0), producing U2 with legs X and h.
# Similarity conditions:
# 1) U1 ~ U2 -> x_cut / y = X / h.
# 2) V1 ~ V2 and bases are horizontal -> base ratio equality: u / x_cut = w / (w - X).
# Eliminating X gives the governing quadratic in y: w*y*y + h*u*y - h*u*v = 0.
try:
    u = int(assign['triangle_leg_x'])
    v = int(assign['triangle_leg_y'])
    w = int(assign['rect_width'])
    h = int(assign['rect_height'])
except Exception:
    # Missing or invalid keys
    return (False, None)
# Domain checks
if not (u > 0 and v > 0 and w > 0 and h > 0):
    return (False, None)
# Solve quadratic for y: w*y^2 + h*u*y - h*u*v = 0 with y>0.
# Discriminant D = h^2*u^2 + 4*w*h*u*v.
from math import isqrt
from fractions import Fraction
D = h*h*u*u + 4*w*h*u*v
sD = isqrt(D)
# Enforce rationality (hardness and to avoid float issues)
if sD * sD != D:
    # Not our engineered family instance; reject
    return (False, None)
# Positive root
yF = Fraction(-h*u + sD, 2*w)
if yF <= 0 or yF >= v:
    # Non-degenerate constraint violated
    return (False, None)
# Compute x_cut and X
x_cutF = Fraction(u) * (Fraction(1) - yF / v)
if x_cutF <= 0:
    return (False, None)
X_F = Fraction(w) * yF / v
# Check triangle similarity: x_cut / y = X / h
# Cross-multiply to avoid division
if x_cutF * h != X_F * yF:
    return (False, None)
# Check trapezoid base ratio equality: u / x_cut = w / (w - X)
# Cross-multiply: u*(w - X) = w*x_cut
if Fraction(u, 1) * (Fraction(w, 1) - X_F) != Fraction(w, 1) * x_cutF:
    return (False, None)
# Angle consistency for trapezoid similarity (implied by U1 ~ U2): slope equality
# Compare y/x_cut with h/X
if yF * X_F != x_cutF * h:
    return (False, None)
# Compute area: (1/2) * x_cut * y
areaF = Fraction(1, 2) * x_cutF * yF
# Express as m/n in lowest terms and return m+n
m_plus_n = areaF.numerator + areaF.denominator
return (True, int(m_plus_n))


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

